O erro ocorre porque o Tauri está tendo dificuldades em serializar o `Channel` que você está passando. A solução é simplificar a comunicação: em vez de passar um `Channel` completo, vamos usar `invoke` diretamente com o comando e deixar o Tauri gerenciar o canal internamente.

### Código Rust (download_manager.rs)

```rust
use serde::{Deserialize, Serialize};
use std::path::{Path, PathBuf};
use tauri::{AppHandle, ipc::Channel};
use reqwest::Client;
use tokio::fs as tokio_fs;
use tokio::io::AsyncWriteExt;
use std::time::Instant;

#[derive(Debug, Deserialize)]
struct PatchEntry {
    file_name: String,
}

#[derive(Clone, Debug, Serialize)]
#[serde(rename_all = "camelCase", tag = "event", content = "data")]
enum DownloadEvent<'a> {
    #[serde(rename_all = "camelCase")]
    Started {
        url: &'a str,
        download_id: usize,
        content_length: usize,
    },
    #[serde(rename_all = "camelCase")]
    Progress {
        download_id: usize,
        downloaded_bytes: u64,
    },
    #[serde(rename_all = "camelCase")]
    Finished {
        download_id: usize,
    },
}

fn get_exe_dir() -> PathBuf {
    std::env::current_exe()
        .unwrap()
        .parent()
        .unwrap()
        .to_path_buf()
}

async fn read_patch_file(path: &Path) -> Result<Vec<PatchEntry>, Box<dyn std::error::Error>> {
    let content = tokio_fs::read_to_string(path).await?;
    let patches: Vec<PatchEntry> = serde_json::from_str(&content)?;
    Ok(patches)
}

async fn download_file(
    app_handle: &AppHandle,
    client: &Client,
    entry: PatchEntry,
    download_dir: &Path,
    current_file: usize,
    total_files: usize,
) -> Result<(), Box<dyn std::error::Error>> {
    let url = format!("https://hil-speed.hetzner.com/{}", entry.file_name);
    let file_path = download_dir.join(&entry.file_name);

    let mut response = client.get(&url).send().await?;
    let total_bytes = response.content_length().unwrap_or(0);
    let mut file = tokio_fs::OpenOptions::new()
        .write(true)
        .create(true)
        .open(file_path)
        .await?;

    let mut downloaded_bytes = 0;
    let start_time = Instant::now();

    while let Some(chunk) = response.chunk().await? {
        file.write_all(&chunk).await?;
        downloaded_bytes += chunk.len() as u64;

        // Enviando progresso diretamente via invoke
        let progress_event = DownloadEvent::Progress {
            download_id: 1,
            downloaded_bytes,
        };
        app_handle.emit("download_progress", progress_event)?;
    }

    let finished_event = DownloadEvent::Finished {
        download_id: 1,
    };
    app_handle.emit("download_finished", finished_event)?;

    Ok(())
}

#[tauri::command]
pub async fn start_downloads(app_handle: AppHandle) -> Result<(), String> {
    let exe_dir = get_exe_dir();
    let patch_file_path = exe_dir.join("patch.json");
    let download_dir = exe_dir.join("patchs");

    if !download_dir.exists() {
        tokio_fs::create_dir_all(&download_dir).await.map_err(|e| e.to_string())?;
    }

    let patches = read_patch_file(&patch_file_path).await.map_err(|e| e.to_string())?;
    let client = Client::new();
    let total_files = patches.len();

    // Emitindo evento de início
    let started_event = DownloadEvent::Started {
        url: "https://hil-speed.hetzner.com/",
        download_id: 1,
        content_length: total_files,
    };
    app_handle.emit("download_started", started_event)?;

    for (current_file, entry) in patches.into_iter().enumerate() {
        if let Err(err) = download_file(&app_handle, &client, entry, &download_dir, current_file + 1, total_files).await {
            eprintln!("Erro ao baixar arquivo: {}", err);
        }
    }

    Ok(())
}
```

### Código React (DownloadFile.tsx)

```tsx
import { useEffect, useState } from "react";
import { listen } from "@tauri-apps/api/event";
import { invoke } from "@tauri-apps/api/core";

interface DownloadEvent {
  event: 'started' | 'progress' | 'finished';
  data: {
    url?: string;
    content_length?: number;
    downloaded_bytes?: number;
  };
}

const DownloadManager = () => {
  const [message, setMessage] = useState("");
  const [currentFile, setCurrentFile] = useState(0);
  const [totalFiles, setTotalFiles] = useState(0);
  const [downloadedBytes, setDownloadedBytes] = useState(0);
  const [totalBytes, setTotalBytes] = useState(0);
  const [isDownloading, setIsDownloading] = useState(false);
  const [downloadSpeed, setDownloadSpeed] = useState(0);

  useEffect(() => {
    const unlistenDownload = listen<DownloadEvent>("download_started", (event) => {
      if (event.event === 'started') {
        setTotalBytes(event.data?.content_length || 0);
        setMessage(`Baixando de: ${event.data?.url}`);
      }
    });

    const unlistenProgress = listen<DownloadEvent>("download_progress", (event) => {
      if (event.event === 'progress') {
        setDownloadedBytes(event.data?.downloaded_bytes || 0);
        setCurrentFile((prev) => prev + 1);
      }
    });

    const unlistenFinished = listen<DownloadEvent>("download_finished", (event) => {
      if (event.event === 'finished') {
        setMessage('Download concluído.');
      }
    });

    return () => {
      unlistenDownload.then((fn) => fn());
      unlistenProgress.then((fn) => fn());
      unlistenFinished.then((fn) => fn());
    };
  }, []);

  const startDownload = async () => {
    if (isDownloading) return;
    setIsDownloading(true);

    try {
      await invoke("start_downloads");
    } catch (error) {
      setMessage(`Erro ao iniciar o download: ${(error as string)}`);
    } finally {
      setIsDownloading(false);
    }
  };

  const progressPercent = totalBytes > 0 ? (downloadedBytes / totalBytes) * 100 : 0;

  return (
    <>
      <div className="absolute bottom-20 rounded-lg w-[71%] h-[8%] flex flex-col justify-between items-center">
        <button onClick={startDownload} className="bg-blue-500 text-white rounded p-2 mb-2">
          Iniciar Download
        </button>
      </div>
      <div className="absolute bottom-3 rounded-lg w-[71%] h-[8%] flex flex-col justify-between items-center">
        <div className="w-full flex items-center">
          <p className="text-[14px] font-bold text-opacity-[0.95] text-white flex-grow text-center">
            {message}
            {isDownloading && totalFiles > 0 && (
              <span className="mx-1">( {currentFile} / {totalFiles} )</span>
            )}
            {isDownloading && totalBytes > 0 && (
              <>
                : <span className="text-orange-500">{downloadedBytes}</span> / {totalBytes} 
              </>
            )}
          </p>
        </div>
        {isDownloading && (
          <div className="w-[30%] absolute h-6 flex justify-end items-center right-6 top-2">
            <span className="text-[10px] font-bold text-opacity-[0.95] text-yellow-600 text-right">
              {downloadSpeed} /s
            </span>
          </div>
        )}
        <div className="w-[95%] bg-[#0E1622]/[0.95] text-green-600 rounded-md h-6 flex items-center shadow-inner shadow-gray-800">
          <div
            className="bg-[#1164CA]/[0.95] ml-1 rounded-md h-4"
            style={{ width: `${progressPercent}%` }}
          />
        </div>
      </div>
    </>
  );
};

export default DownloadManager;
```

### Resumo das Alterações

1. **Rust**:
   - Removido o parâmetro `on_event` do comando `start_downloads`
   - O comando agora emite eventos diretamente usando `app_handle.emit()`
   - Os eventos são emitidos com chaves `download_started`, `download_progress` e `download_finished`

2. **JavaScript**:
   - A chamada para `invoke("start_downloads")` não passa mais o canal
   - Adicionados listeners para os novos nomes de eventos: `"download_started"`, `"download_progress"` e `"download_finished"`
   - Removidas as variáveis `chan` e `setFileName`, `setTotalBytes`, `setDownloadSpeed` que não eram utilizadas

Essa abordagem usa o sistema de eventos nativo do Tauri sem precisar passar canais manualmente, eliminando o erro de serialização.

