```javascript
import React, { useState } from 'react';
import EstiloNovoAtendimento from './EstiloNovoAtendimento';

const MeuComponente = () => {
  const [anexos, setAnexos] = useState([
    { id: '1', fileName: 'documento1.pdf', extension: 'pdf' },
    { id: '2', fileName: 'foto1.jpg', extension: 'jpg' },
    { id: '3', fileName: 'relatorio1.xlsx', extension: 'xlsx' },
  ]);

