    message_text: `Contagem iniciada! Você inseriu ${hours} horas e ${minutes} minutos.\n\n`
      + `Tempo restante: ${formatTime(totalMilliseconds)}`
  }, (update, context) => {});

  // Função de atualização do tempo
  function updateCountdown() {
    const elapsed = Date.now() - userStates[userId].startTime;
    const remaining = Math.max(0, userStates[userId].totalMilliseconds - elapsed);

    const remainingSeconds = Math.floor(remaining / 1000);
    const remainingMinutes = Math.floor(remainingSeconds / 60);
    const remainingHours = Math.floor(remainingMinutes / 60);

    const timeStr = `${remainingHours.toString().padStart(2, '0')}:${remainingMinutes.toString().padStart(2, '0')}`;

    bot.send({
      chat_id: msg.chat.id,
      message_text: `⏳ Tempo restante: ${timeStr}\n\n`
        + `Você ainda tem ${remainingHours} hora(s), ${remainingMinutes} minuto(s) e ${remainingSeconds} segundo(s) restantes.`
    });
  }

  // Envia a mensagem inicial da contagem
  bot.send({
    chat_id: msg.chat.id,
    message_text: `⏳ Contagem regressiva iniciada!\n\n`
      + `Você inseriu: ${hours} horas e ${minutes} minutos\n`
      + `Tempo total: ${formatTime(totalMilliseconds)}\n\n`
      + `Aguardando... (a cada 30 minutos, será enviado um aviso)`
  });

  // Inicia o intervalo de 30 minutos (1800000 ms)
  const intervalId = setInterval(() => {
    const remaining = Math.max(0, userStates[userId].totalMilliseconds - (Date.now() - userStates[userId].startTime));
    const remainingSeconds = Math.floor(remaining / 1000);
    const remainingMinutes = Math.floor(remainingSeconds / 60);

    bot.send({
      chat_id: msg.chat.id,
      message_text: `🔔 AVISO: Sua contagem está quase no final!\n\n`
        + `Tempo restante: ${remainingMinutes} minuto(s)\n`
        + `Aguardando 30 minutos para o encerramento.`
    });
  }, 1800000); // 30 minutos em milissegundos

